BEGIN TRANSACTION;
CREATE TABLE "accesorios" (
"ID" TEXT,
  "Categoria" TEXT,
  "Accesorio" TEXT,
  "Detalle" TEXT,
  "Metodo" TEXT,
  "K_tabla" REAL,
  "Angulo_grados" REAL,
  "r_D" REAL,
  "kt" REAL,
  "t_mm" REAL,
  "b_mm" REAL,
  "phi_grados" REAL,
  "Fuente" TEXT,
  "Nota" TEXT
);
CREATE TABLE "accesorios_fuentes" (
"Clave" TEXT,
  "Referencia" TEXT,
  "Datos que respalda" TEXT
);
CREATE TABLE "caudales_rio" (
"dia" INTEGER,
  "Q_rio_m3s" REAL
);
CREATE TABLE "dataset_hidraulico" (
"scenario_id" TEXT,
  "Q_m3s" REAL,
  "L_m" REAL,
  "H_bruto_m" REAL,
  "epsilon_mm" REAL,
  "K_total" REAL,
  "rho_kgm3" REAL,
  "nu_m2s" REAL,
  "g_ms2" REAL,
  "eta_t" REAL,
  "eta_g" REAL,
  "fraccion_perdida_max" REAL,
  "D_m" REAL,
  "V_ms" REAL,
  "Re" REAL,
  "regimen" TEXT,
  "f_Darcy" REAL,
  "hf_m" REAL,
  "hm_m" REAL,
  "hL_m" REAL,
  "H_neto_m" REAL,
  "P_h_MW" REAL,
  "P_e_MW" REAL,
  "loss_frac" REAL,
  "factible" INTEGER,
  "motivo" TEXT,
  "dataset_version" TEXT,
  "physics_engine" TEXT,
  "source_geometry" TEXT,
  "source_K" TEXT
);
CREATE TABLE "metadatos" (
"tabla" TEXT,
  "descripcion" TEXT,
  "archivo_fuente" TEXT,
  "filas" INTEGER,
  "creada" TEXT
);
CREATE TABLE "precios_xm" (
"periodo_mes" TEXT,
  "variable" TEXT,
  "valor" REAL,
  "unidad" TEXT,
  "url" TEXT,
  "fecha_publicacion" TEXT,
  "fecha_consulta" TEXT,
  "metodo" TEXT,
  "lectura" TEXT,
  "notas" TEXT
);
CREATE TABLE "tuberias_diametros" (
"Material_ID" TEXT,
  "Material" TEXT,
  "Fabricante" TEXT,
  "Serie_Producto" TEXT,
  "Norma_Clase" TEXT,
  "DN_mm" INTEGER,
  "OD_mm" REAL,
  "Espesor_mm" REAL,
  "ID_hidraulico_mm" REAL,
  "Diametro_hidraulico_m" REAL,
  "Disponible_catalogo" INTEGER,
  "Fuente_catalogo" TEXT,
  "Observacion" TEXT
);
CREATE TABLE "tuberias_fuentes" (
"Tema" TEXT,
  "Fuente" TEXT,
  "Dato respaldado" TEXT,
  "Nota" TEXT
);
CREATE TABLE "tuberias_materiales" (
"Material_ID" TEXT,
  "Material" TEXT,
  "Familia" TEXT,
  "Uso_PCH" TEXT,
  "epsilon_diseno_mm" REAL,
  "epsilon_min_mm" REAL,
  "epsilon_max_mm" REAL,
  "Criterio_epsilon" TEXT,
  "Tipo_dimensionamiento" TEXT,
  "Fuente_rugosidad" TEXT,
  "Fuente_catalogo" TEXT,
  "Notas" TEXT
);
CREATE TABLE "tuberias_rangos" (
"Material_ID" TEXT,
  "Material" TEXT,
  "Mínimo comercial/fabricación [mm]" TEXT,
  "Máximo comercial/fabricación [mm]" TEXT,
  "¿Llega a 6000 mm?" TEXT,
  "Tipo de disponibilidad" TEXT,
  "Uso recomendado en la iteración" TEXT,
  "Fuente" TEXT
);
CREATE VIEW v_catalogo_tuberias AS SELECT d.*, m.epsilon_diseno_mm FROM tuberias_diametros d LEFT JOIN tuberias_materiales m USING (Material_ID);
CREATE INDEX ix_diametros_material ON tuberias_diametros (Material_ID);
COMMIT;
